const b04RemovalRouteTargets = `-- name: B04RemovalRouteTargets :many
SELECT DISTINCT peer.node_id,peer.listener_id FROM route_hops gone
JOIN routes r ON r.id=gone.route_id AND r.published_revision=gone.revision
JOIN route_hops peer ON peer.route_id=gone.route_id AND peer.revision=gone.revision
WHERE gone.node_id=? AND peer.node_id!=gone.node_id
ORDER BY peer.node_id,peer.listener_id
`

type B04RemovalRouteTargetsRow struct {
	NodeID     string
	ListenerID string
}

func (q *Queries) B04RemovalRouteTargets(ctx context.Context, nodeID string) ([]B04RemovalRouteTargetsRow, error) {
	rows, err := q.db.QueryContext(ctx, b04RemovalRouteTargets, nodeID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []B04RemovalRouteTargetsRow
	for rows.Next() {
		var i B04RemovalRouteTargetsRow
		if err := rows.Scan(&i.NodeID, &i.ListenerID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

